/**
 * sdk-spec — turn the mirrored 1Password SDK description (`specs/sdk/`) into
 * an OpenAPI 3.1 document the shared OpenAPI→Smithy converter understands.
 *
 * Package-local dialect (AGENTS.md rule 6). Two inputs, both mirrored from the
 * upstream `onepassword-sdk-js` release's `client/src`:
 *
 *   • `types.ts`  — generated by typeshare; every interface / enum / type alias
 *                   becomes a component schema.
 *   • `*.ts` API modules (op-codegen) — every class method that builds an
 *                   `invocation` object literal becomes `POST /<InvocationName>`;
 *                   the invocation name and parameter keys come from the literal,
 *                   the parameter / return types from the method signature.
 *
 * The converter is generic over those constructs and names no shape or member;
 * `SDK_OPERATION_NAMES` is the one sanctioned naming table.
 *
 * Also here: `typeshareConstants` (the `export const NAME: number = N` flags)
 * and `checkSdkPins` (fails `pnpm generate` when the hand-written pins in
 * `src/` drift from the mirrored release).
 */
import * as fs from "node:fs";
import * as path from "node:path";
import { parseSync } from "oxc-parser";

// oxc's ESTree-style AST is walked structurally; its node union is too wide to type by hand.
type AstNode = any;
type Schema = Record<string, unknown>;

/** Invocation name → generated export name. A name missing here keeps the converter's default. */
export const SDK_OPERATION_NAMES: Record<string, string> = {
  SecretsResolve: "resolveSecret",
  SecretsResolveAll: "resolveSecrets",
  ItemsCreate: "createItem",
  ItemsCreateAll: "createItems",
  ItemsGet: "getItem",
  ItemsGetAll: "getItems",
  ItemsPut: "putItem",
  ItemsDelete: "deleteItem",
  ItemsDeleteAll: "deleteItems",
  ItemsArchive: "archiveItem",
  ItemsList: "listItems",
  ItemsFilesAttach: "attachItemFile",
  ItemsFilesRead: "readItemFile",
  ItemsFilesDelete: "deleteItemFile",
  ItemsFilesReplaceDocument: "replaceItemDocument",
  ItemsSharesGetAccountPolicy: "getItemShareAccountPolicy",
  ItemsSharesValidateRecipients: "validateItemShareRecipients",
  ItemsSharesCreate: "createItemShare",
  VaultsCreate: "createVault",
  VaultsList: "listVaults",
  VaultsGetOverview: "getVaultOverview",
  VaultsGet: "getVault",
  VaultsUpdate: "updateVault",
  VaultsDelete: "deleteVault",
  VaultsGrantGroupPermissions: "grantVaultGroupPermissions",
  VaultsUpdateGroupPermissions: "updateVaultGroupPermissions",
  VaultsRevokeGroupPermissions: "revokeVaultGroupPermissions",
  GroupsGet: "getGroup",
  EnvironmentsGetVariables: "getEnvironmentVariables",
  ValidateSecretReference: "validateSecretReference",
  GeneratePassword: "generatePassword",
};

/** Files in the mirror that are not API modules. */
const NON_API_FILES = new Set(["types.ts", "version.ts", "errors.ts"]);

// ---------------------------------------------------------------------------
// Parsing helpers
// ---------------------------------------------------------------------------

interface Source {
  readonly file: string;
  readonly text: string;
  readonly program: AstNode;
  readonly comments: ReadonlyArray<{ type: string; value: string; start: number; end: number }>;
}

const parseSource = (file: string, text: string): Source => {
  const result = parseSync(file, text, { lang: "ts" });
  if (result.errors.length > 0) {
    const first = result.errors[0] as { message: string };
    throw new Error(`typeshare: failed to parse ${file}: ${first.message}`);
  }
  return { file, text, program: result.program, comments: result.comments as Source["comments"] };
};

const lineOf = (src: Source, offset: number): number => {
  let line = 1;
  for (let i = 0; i < offset && i < src.text.length; i++) if (src.text[i] === "\n") line++;
  return line;
};

const unsupported = (src: Source, node: AstNode): Error =>
  new Error(`typeshare: unsupported ${node.type} at ${src.file}:${lineOf(src, node.start)}`);

const cleanDoc = (value: string): string =>
  value
    .split("\n")
    .map((l) => l.replace(/^\s*\*? ?/, "").trimEnd())
    .join("\n")
    .trim();

/** The last `/** *\/` comment ending before `start`, with only whitespace or `|` between. */
const docBefore = (src: Source, start: number): string | undefined => {
  let found: string | undefined;
  for (const c of src.comments) {
    if (c.type !== "Block" || !c.value.startsWith("*") || c.end > start) continue;
    if (/^[\s|]*$/.test(src.text.slice(c.end, start))) {
      const doc = cleanDoc(c.value.slice(1));
      found = doc === "" ? undefined : doc;
    }
  }
  return found;
};

const pascal = (s: string): string => s.charAt(0).toUpperCase() + s.slice(1);

const keyName = (src: Source, key: AstNode): string => {
  if (key.type === "Identifier") return key.name;
  if (key.type === "Literal") return String(key.value);
  throw unsupported(src, key);
};

const ref = (name: string): Schema => ({ $ref: `#/components/schemas/${name}` });

// ---------------------------------------------------------------------------
// typeshare types.ts → component schemas
// ---------------------------------------------------------------------------

interface TypeCtx {
  readonly src: Source;
  /** Component-name prefix for inline object literals. */
  readonly owner: string;
  /** The property / parameter the type belongs to; names inline object literals. */
  readonly key?: string;
  /** Generic parameter → converted argument (`null` is `undefined`: omitted). */
  readonly subst?: ReadonlyMap<string, Schema | null>;
}

interface TypeConverter {
  readonly schemas: Record<string, Schema>;
  /** `null` for the `undefined` type (the caller omits the member). */
  readonly convert: (node: AstNode, ctx: TypeCtx) => Schema | null;
}

const makeTypeConverter = (types: Source): TypeConverter => {
  const schemas: Record<string, Schema> = {};
  const generics = new Map<string, AstNode>();

  const define = (src: Source, node: AstNode, name: string, schema: Schema): void => {
    if (name in schemas) {
      throw new Error(
        `typeshare: duplicate schema ${name} at ${src.file}:${lineOf(src, node.start)}`,
      );
    }
    schemas[name] = schema;
  };

  const typeArgName = (src: Source, node: AstNode): string => {
    if (node.type === "TSUndefinedKeyword") return "Unit";
    if (
      node.type === "TSTypeReference" &&
      node.typeName.type === "Identifier" &&
      !node.typeArguments
    ) {
      return node.typeName.name;
    }
    throw unsupported(src, node);
  };

  const instantiate = (node: AstNode, name: string, ctx: TypeCtx): Schema => {
    const decl = generics.get(name);
    const params: string[] = decl.typeParameters.params.map((p: AstNode) => p.name.name);
    const args: AstNode[] = node.typeArguments?.params ?? [];
    if (args.length !== params.length) throw unsupported(ctx.src, node);
    const component = name + args.map((a) => typeArgName(ctx.src, a)).join("");
    if (!(component in schemas)) {
      const subst = new Map<string, Schema | null>();
      params.forEach((p, i) => subst.set(p, convert(args[i], ctx)));
      // Reserve the name first so a self-referential instantiation terminates.
      schemas[component] = {};
      schemas[component] = objectSchema(types, decl.body.body, component, subst);
    }
    return ref(component);
  };

  const convert = (node: AstNode, ctx: TypeCtx): Schema | null => {
    switch (node.type) {
      case "TSStringKeyword":
        return { type: "string" };
      case "TSNumberKeyword":
        return { type: "number" };
      case "TSBooleanKeyword":
        return { type: "boolean" };
      case "TSUndefinedKeyword":
        return null;
      case "TSLiteralType":
        if (node.literal.type === "Literal" && typeof node.literal.value === "string") {
          return { type: "string", enum: [node.literal.value] };
        }
        throw unsupported(ctx.src, node);
      case "TSArrayType": {
        const items = convert(node.elementType, ctx);
        if (items === null) throw unsupported(ctx.src, node);
        return { type: "array", items };
      }
      case "TSTypeLiteral": {
        if (ctx.key === undefined) throw unsupported(ctx.src, node);
        const name = ctx.owner + pascal(ctx.key);
        define(ctx.src, node, name, objectSchema(ctx.src, node.members, name, ctx.subst));
        return ref(name);
      }
      case "TSTypeReference": {
        if (node.typeName.type !== "Identifier") throw unsupported(ctx.src, node);
        const name: string = node.typeName.name;
        const subst = ctx.subst?.get(name);
        if (subst !== undefined) return subst;
        const args: AstNode[] = node.typeArguments?.params ?? [];
        if (name === "Date") return { type: "string", format: "date-time" };
        if (name === "Uint8Array") {
          return { type: "array", items: { type: "integer", minimum: 0, maximum: 255 } };
        }
        if (name === "Array" && args.length === 1) {
          const items = convert(args[0], ctx);
          if (items === null) throw unsupported(ctx.src, node);
          return { type: "array", items };
        }
        if (name === "Record" && args.length === 2 && args[0].type === "TSStringKeyword") {
          const value = convert(args[1], ctx);
          if (value === null) throw unsupported(ctx.src, node);
          return { type: "object", additionalProperties: value };
        }
        if (generics.has(name)) return instantiate(node, name, ctx);
        return ref(name);
      }
      default:
        throw unsupported(ctx.src, node);
    }
  };

  /** Members of an interface body / type literal → object schema. */
  const objectSchema = (
    src: Source,
    members: AstNode[],
    owner: string,
    subst?: ReadonlyMap<string, Schema | null>,
    extra?: Record<string, Schema>,
  ): Schema => {
    const properties: Record<string, Schema> = { ...extra };
    const required: string[] = extra ? Object.keys(extra) : [];
    for (const m of members) {
      if (m.type !== "TSPropertySignature" || !m.typeAnnotation) throw unsupported(src, m);
      const key = keyName(src, m.key);
      if (key in properties) continue; // an arm's explicit `type` member wins over `extra`
      const schema = convert(m.typeAnnotation.typeAnnotation, { src, owner, key, subst });
      if (schema === null) continue;
      const description = docBefore(src, m.start);
      properties[key] = description === undefined ? schema : { ...schema, description };
      if (!m.optional) required.push(key);
    }
    return {
      type: "object",
      properties,
      ...(required.length > 0 ? { required } : {}),
    };
  };

  const withDoc = (schema: Schema, description: string | undefined): Schema =>
    description === undefined ? schema : { ...schema, description };

  /** The string-literal `type` member of an object literal, if any. */
  const tagOf = (lit: AstNode): string | undefined => {
    for (const m of lit.members) {
      if (
        m.type === "TSPropertySignature" &&
        m.key.type === "Identifier" &&
        m.key.name === "type" &&
        m.typeAnnotation?.typeAnnotation.type === "TSLiteralType" &&
        typeof m.typeAnnotation.typeAnnotation.literal.value === "string"
      ) {
        return m.typeAnnotation.typeAnnotation.literal.value;
      }
    }
    return undefined;
  };

  // Pass 1: generics must be known before any instantiation is met.
  const declarations: Array<{ decl: AstNode; doc: string | undefined }> = [];
  for (const stmt of types.program.body as AstNode[]) {
    const decl = stmt.type === "ExportNamedDeclaration" ? stmt.declaration : stmt;
    if (!decl) throw unsupported(types, stmt);
    if (decl.type === "VariableDeclaration") continue; // constants: see typeshareConstants
    if (decl.type === "TSInterfaceDeclaration" && decl.typeParameters) {
      generics.set(decl.id.name, decl);
      continue;
    }
    declarations.push({ decl, doc: docBefore(types, stmt.start) });
  }

  // Pass 2: convert.
  for (const { decl, doc } of declarations) {
    const name: string = decl.id.name;
    switch (decl.type) {
      case "TSInterfaceDeclaration":
        define(types, decl, name, withDoc(objectSchema(types, decl.body.body, name), doc));
        break;
      case "TSEnumDeclaration": {
        const values = (decl.body.members as AstNode[]).map((m) => {
          if (m.initializer?.type !== "Literal" || typeof m.initializer.value !== "string") {
            throw unsupported(types, m);
          }
          return m.initializer.value as string;
        });
        define(types, decl, name, withDoc({ type: "string", enum: values }, doc));
        break;
      }
      case "TSTypeAliasDeclaration": {
        if (decl.typeParameters) throw unsupported(types, decl);
        const t = decl.typeAnnotation;
        if (t.type === "TSStringKeyword") {
          define(types, decl, name, withDoc({ type: "string" }, doc));
        } else if (t.type === "TSTypeLiteral") {
          define(types, decl, name, withDoc(objectSchema(types, t.members, name), doc));
        } else if (
          t.type === "TSUnionType" &&
          (t.types as AstNode[]).every((a) => a.type === "TSTypeLiteral" && tagOf(a) !== undefined)
        ) {
          const arms: Schema[] = [];
          for (const arm of t.types as AstNode[]) {
            const tag = tagOf(arm) as string;
            const armName = name + pascal(tag);
            define(
              types,
              arm,
              armName,
              withDoc(
                objectSchema(types, arm.members, armName, undefined, {
                  type: { type: "string", enum: [tag] },
                }),
                docBefore(types, arm.start),
              ),
            );
            arms.push(ref(armName));
          }
          define(
            types,
            decl,
            name,
            withDoc({ oneOf: arms, discriminator: { propertyName: "type" } }, doc),
          );
        } else {
          throw unsupported(types, t);
        }
        break;
      }
      default:
        throw unsupported(types, decl);
    }
  }

  return { schemas, convert };
};

// ---------------------------------------------------------------------------
// op-codegen API modules → paths
// ---------------------------------------------------------------------------

/** First `ObjectExpression` below `node` that has an `invocation` property. */
const findInvocationHolder = (node: AstNode): AstNode | undefined => {
  if (node === null || typeof node !== "object") return undefined;
  if (Array.isArray(node)) {
    for (const n of node) {
      const hit = findInvocationHolder(n);
      if (hit) return hit;
    }
    return undefined;
  }
  if (
    node.type === "ObjectExpression" &&
    (node.properties as AstNode[]).some(
      (p) => p.type === "Property" && p.key.type === "Identifier" && p.key.name === "invocation",
    )
  ) {
    return node;
  }
  for (const k of Object.keys(node)) {
    const hit = findInvocationHolder(node[k]);
    if (hit) return hit;
  }
  return undefined;
};

const objectProp = (src: Source, obj: AstNode, name: string): AstNode | undefined => {
  if (obj?.type !== "ObjectExpression")
    throw unsupported(src, obj ?? { type: "undefined", start: 0 });
  for (const p of obj.properties as AstNode[]) {
    if (p.type !== "Property") throw unsupported(src, p);
    if (keyName(src, p.key) === name) return p.value;
  }
  return undefined;
};

interface MethodParam {
  readonly type: AstNode;
  readonly required: boolean;
}

const methodParams = (src: Source, fn: AstNode): Map<string, MethodParam> => {
  const out = new Map<string, MethodParam>();
  for (const p of fn.params as AstNode[]) {
    if (p.type === "Identifier" && p.typeAnnotation) {
      out.set(p.name, { type: p.typeAnnotation.typeAnnotation, required: !p.optional });
    } else if (
      p.type === "AssignmentPattern" &&
      p.left.type === "Identifier" &&
      p.left.typeAnnotation
    ) {
      out.set(p.left.name, { type: p.left.typeAnnotation.typeAnnotation, required: false });
    } else if (
      p.type === "RestElement" &&
      p.argument.type === "Identifier" &&
      p.typeAnnotation?.typeAnnotation.type === "TSArrayType"
    ) {
      out.set(p.argument.name, { type: p.typeAnnotation.typeAnnotation, required: true });
    } else {
      throw unsupported(src, p);
    }
  }
  return out;
};

const apiPaths = (
  dir: string,
  files: ReadonlyArray<string>,
  types: TypeConverter,
): Record<string, unknown> => {
  const paths: Record<string, unknown> = {};
  const seen = new Map<string, string>();
  for (const file of files) {
    const filePath = path.join(dir, file);
    const src = parseSource(filePath, fs.readFileSync(filePath, "utf8"));
    for (const stmt of src.program.body as AstNode[]) {
      const decl = stmt.type === "ExportNamedDeclaration" ? stmt.declaration : stmt;
      if (decl?.type !== "ClassDeclaration") continue;
      for (const member of decl.body.body as AstNode[]) {
        if (member.type !== "MethodDefinition" || member.kind !== "method") continue;
        const fn = member.value;
        const holder = findInvocationHolder(fn.body);
        if (!holder) continue;
        const where = `${decl.id.name}.${keyName(src, member.key)}`;
        const invocation = objectProp(src, holder, "invocation");
        const parameters = objectProp(src, invocation, "parameters");
        const nameNode = objectProp(src, parameters, "name");
        if (nameNode?.type !== "Literal" || typeof nameNode.value !== "string") {
          throw new Error(
            `typeshare: ${where} in ${src.file}: invocation name must be a string literal`,
          );
        }
        const name: string = nameNode.value;
        const previous = seen.get(name);
        if (previous !== undefined) {
          throw new Error(`typeshare: invocation ${name} is used by both ${previous} and ${where}`);
        }
        seen.set(name, where);

        const method = methodParams(src, fn);
        const valuesNode = objectProp(src, parameters, "parameters");
        const properties: Record<string, Schema> = {};
        const required: string[] = [];
        if (valuesNode) {
          if (valuesNode.type !== "ObjectExpression") throw unsupported(src, valuesNode);
          for (const p of valuesNode.properties as AstNode[]) {
            if (p.type !== "Property" || p.value.type !== "Identifier") throw unsupported(src, p);
            const param = method.get(p.value.name);
            if (!param) {
              throw new Error(
                `typeshare: ${where} in ${src.file}: invocation parameter ${p.value.name} is not a method parameter`,
              );
            }
            const key = keyName(src, p.key);
            const schema = types.convert(param.type, { src, owner: name, key });
            if (schema === null) throw unsupported(src, param.type);
            properties[key] = schema;
            if (param.required) required.push(key);
          }
        }

        let returned: AstNode = fn.returnType?.typeAnnotation;
        if (!returned) throw unsupported(src, member);
        if (returned.type === "TSTypeReference" && returned.typeName.name === "Promise") {
          returned = returned.typeArguments?.params?.[0];
          if (!returned) throw unsupported(src, member);
        }
        const responseSchema =
          returned.type === "TSVoidKeyword"
            ? undefined
            : types.convert(returned, { src, owner: name, key: "Response" });

        const description = docBefore(src, member.start);
        paths[`/${name}`] = {
          post: {
            operationId: name,
            ...(description === undefined ? {} : { description }),
            "x-onepassword-client": objectProp(src, invocation, "clientId") !== undefined,
            requestBody: {
              required: required.length > 0,
              content: {
                "application/json": {
                  schema: {
                    type: "object",
                    properties,
                    ...(required.length > 0 ? { required } : {}),
                  },
                },
              },
            },
            responses:
              responseSchema === undefined || responseSchema === null
                ? { "204": { description: "No content" } }
                : {
                    "200": {
                      description: "OK",
                      content: { "application/json": { schema: responseSchema } },
                    },
                  },
          },
        };
      }
    }
  }
  if (Object.keys(paths).length === 0) {
    throw new Error(`typeshare: no op-codegen operation found in ${dir}`);
  }
  return paths;
};

const collectRefs = (node: unknown, out: Set<string>): void => {
  if (node === null || typeof node !== "object") return;
  if (Array.isArray(node)) {
    for (const n of node) collectRefs(n, out);
    return;
  }
  for (const [k, v] of Object.entries(node)) {
    if (k === "$ref" && typeof v === "string") out.add(v);
    else collectRefs(v, out);
  }
};

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

const VERSION_CONST = /(?:export )?const (\w+) = "([^"]+)"/g;

const readConstants = (text: string, pattern: RegExp): Map<string, string> => {
  const out = new Map<string, string>();
  for (const m of text.matchAll(pattern)) out.set(m[1] as string, m[2] as string);
  return out;
};

/** typeshare `types.ts` + sibling op-codegen modules → one OpenAPI 3.1 document. */
export const sdkOpenApi = (typesText: string, typesPath: string): Record<string, unknown> => {
  const dir = path.dirname(typesPath);
  const types = makeTypeConverter(parseSource(typesPath, typesText));
  const files = fs
    .readdirSync(dir)
    .filter((f) => f.endsWith(".ts") && !NON_API_FILES.has(f))
    .sort();
  const paths = apiPaths(dir, files, types);

  const missing = new Set<string>();
  const refs = new Set<string>();
  collectRefs(paths, refs);
  collectRefs(types.schemas, refs);
  for (const r of refs) {
    const name = r.replace("#/components/schemas/", "");
    if (!(name in types.schemas)) missing.add(name);
  }
  if (missing.size > 0) {
    throw new Error(`typeshare: unresolved type reference(s): ${[...missing].join(", ")}`);
  }

  const version = readConstants(
    fs.readFileSync(path.join(dir, "version.ts"), "utf8"),
    VERSION_CONST,
  ).get("SDK_VERSION");
  if (version === undefined)
    throw new Error(`typeshare: SDK_VERSION not found in ${path.join(dir, "version.ts")}`);

  return {
    openapi: "3.1.0",
    info: { title: "1Password SDK", version },
    paths,
    components: { schemas: types.schemas },
  };
};

interface SdkOpenApiDoc {
  paths: Record<string, { post: Record<string, unknown> }>;
}

/** Keep the operations whose `x-onepassword-client` equals `client`; drops the marker. */
export const selectSdkOperations = <D extends SdkOpenApiDoc>(doc: D, client: boolean): D => {
  const paths: SdkOpenApiDoc["paths"] = {};
  for (const [p, item] of Object.entries(doc.paths)) {
    if (item.post["x-onepassword-client"] !== client) continue;
    const { "x-onepassword-client": _marker, ...post } = item.post;
    paths[p] = { ...item, post };
  }
  doc.paths = paths;
  return doc;
};

/** Every `export const NAME: number = <numeric literal>` in typeshare output. */
export const typeshareConstants = (
  typesText: string,
): Array<{ name: string; value: number; doc?: string }> => {
  const src = parseSource("types.ts", typesText);
  const out: Array<{ name: string; value: number; doc?: string }> = [];
  for (const stmt of src.program.body as AstNode[]) {
    const decl = stmt.type === "ExportNamedDeclaration" ? stmt.declaration : undefined;
    if (decl?.type !== "VariableDeclaration" || decl.kind !== "const") continue;
    for (const d of decl.declarations as AstNode[]) {
      if (
        d.id.type !== "Identifier" ||
        d.id.typeAnnotation?.typeAnnotation.type !== "TSNumberKeyword" ||
        d.init?.type !== "Literal" ||
        typeof d.init.value !== "number"
      ) {
        continue;
      }
      const doc = docBefore(src, stmt.start);
      out.push({ name: d.id.name, value: d.init.value, ...(doc === undefined ? {} : { doc }) });
    }
  }
  return out;
};

const readText = (file: string): string => {
  try {
    return fs.readFileSync(file, "utf8");
  } catch (cause) {
    throw new Error(`sdk pin check: cannot read ${file}: ${(cause as Error).message}`);
  }
};

/** Fail when the hand-written pins in `src/` / `package.json` drift from the mirrored release. */
export const checkSdkPins = (sdkDir: string, packageRoot: string): void => {
  const mirroredVersionFile = path.join(sdkDir, "version.ts");
  const localVersionFile = path.join(packageRoot, "src/sdk-version.ts");
  const mirrored = readConstants(readText(mirroredVersionFile), VERSION_CONST);
  const local = readConstants(readText(localVersionFile), /export const (\w+) = "([^"]+)"/g);
  for (const name of ["SDK_BUILD_NUMBER", "SDK_VERSION", "SDK_CORE_VERSION"]) {
    const upstream = mirrored.get(name);
    const pinned = local.get(name);
    if (upstream === undefined) {
      throw new Error(`${mirroredVersionFile}: ${name} not found`);
    }
    if (pinned !== upstream) {
      throw new Error(
        `${localVersionFile}: ${name} is ${JSON.stringify(pinned)} but the mirrored ${mirroredVersionFile} has ${JSON.stringify(upstream)}`,
      );
    }
  }

  const releaseFile = path.join(sdkDir, "release.json");
  const packageFile = path.join(packageRoot, "package.json");
  const release = JSON.parse(readText(releaseFile)) as { sdkCoreVersion?: string };
  const pkg = JSON.parse(readText(packageFile)) as {
    peerDependencies?: Record<string, string>;
  };
  const peer = pkg.peerDependencies?.["@1password/sdk-core"];
  if (peer !== release.sdkCoreVersion) {
    throw new Error(
      `${packageFile}: peerDependencies["@1password/sdk-core"] is ${JSON.stringify(peer)} but ${releaseFile} sdkCoreVersion is ${JSON.stringify(release.sdkCoreVersion)}`,
    );
  }

  const errorsFile = path.join(sdkDir, "errors.ts");
  const localErrorsFile = path.join(packageRoot, "src/errors.ts");
  const localErrors = readText(localErrorsFile);
  for (const m of readText(errorsFile).matchAll(/case "(\w+)":/g)) {
    const tag = m[1] as string;
    if (!localErrors.includes(`("${tag}"`)) {
      throw new Error(
        `${localErrorsFile}: no error class tagged ("${tag}") but upstream ${errorsFile} throws it`,
      );
    }
  }
};
